import numpy as np
from PIL import Image
im = Image.open('/app/radiograph.jpg').convert('L')
a = np.asarray(im).astype(np.float32)
def stretch(tile, lo=1, hi=99):
    v1, v2 = np.percentile(tile, lo), np.percentile(tile, hi)
    return np.clip((tile - v1) / max(v2 - v1, 1) * 255, 0, 255)
crops = {
 'v_ur56': (960, 400, 1180, 620),
 'v_ur12': (1240, 380, 1460, 600),
 'v_ul34': (1470, 380, 1700, 620),
}
for name, (x1,y1,x2,y2) in crops.items():
    t = stretch(a[y1:y2, x1:x2])
    img = Image.fromarray(t.astype(np.uint8))
    img = img.resize((img.width*5, img.height*5), Image.LANCZOS)
    img.save(f'/tmp/crops/{name}.png')
print('ok')
